'use strict';

/**
* Test whether two provided values have the same constructor.
*
* @module @stdlib/assert/has-same-constructor
*
* @example
* var hasSameConstructor = require( '@stdlib/assert/has-same-constructor' );
*
* @example
* var x = new Number(5);
* var y = new Number(10);
* var bool = hasSameConstructor( x, y );
* // returns true
*
* @example
* var x = new Number(5);
* var y = [];
* var bool = hasSameConstructor( x, y );
* // returns false
*
* @example
* var x = [];
* var y = [];
* var bool = hasSameConstructor( x, y );
* // returns true
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
